class AppError extends Error {
  constructor(message, { status = 500, code = "INTERNAL", cause } = {}) {
    super(message, { cause });
    this.name = this.constructor.name;
    this.status = status;
    this.code = code;
  }
}
class NotFoundError extends AppError {
  constructor(what) { super(what + " không tồn tại", { status: 404, code: "NOT_FOUND" }); }
}
class ValidationError extends AppError {
  constructor(msg) { super(msg, { status: 400, code: "VALIDATION" }); }
}

function toHttp(err) {
  if (err instanceof AppError) return { status: err.status, body: { error: err.code, message: err.message } };
  return { status: 500, body: { error: "INTERNAL", message: "Lỗi hệ thống" } };   // không lộ chi tiết
}

console.log(JSON.stringify(toHttp(new NotFoundError("Bài viết"))));
console.log(JSON.stringify(toHttp(new TypeError("x is undefined"))));

