const db = () => { throw new Error("connection refused"); };
function loadUser(id) {
  try { return db(); }
  catch (e) { throw new Error("Could not load user " + id, { cause: e }); }
}
try { loadUser(7); } catch (e) { console.log(e.message + "|" + e.cause.message); }
